export const html = "<!doctype html>\n<html lang=\"it\">\n  <head>\n    <meta charset=\"utf-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\" />\n    <meta\n      name=\"description\"\n      content=\"Una webapp privacy-first per controllare dove una mail potrebbe essere stata usata e organizzare la pulizia degli account.\"\n    />\n    <meta property=\"og:title\" content=\"Account Finder Mail\" />\n    <meta\n      property=\"og:description\"\n      content=\"Checklist, ricerche pronte, note locali e piano di pulizia per account collegati a una email.\"\n    />\n    <title>Account Finder Mail</title>\n    <style>\n      :root {\n        color-scheme: light;\n        --paper: #f7f8f4;\n        --surface: #ffffff;\n        --surface-2: #edf4ef;\n        --ink: #15191d;\n        --muted: #5c6670;\n        --line: #d4ddd8;\n        --strong: #0c6b5d;\n        --strong-2: #235f9c;\n        --accent: #c76b25;\n        --danger: #aa3434;\n        --ok: #16805f;\n        --night: #111b20;\n        --shadow: 0 22px 54px rgba(20, 30, 28, 0.12);\n      }\n\n      * {\n        box-sizing: border-box;\n      }\n\n      body {\n        margin: 0;\n        background:\n          linear-gradient(125deg, rgba(12, 107, 93, 0.12), transparent 34%),\n          linear-gradient(215deg, rgba(199, 107, 37, 0.12), transparent 30%),\n          linear-gradient(180deg, #fbfaf7 0%, var(--paper) 46%, #edf3ef 100%);\n        color: var(--ink);\n        font-family:\n          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,\n          \"Segoe UI\", sans-serif;\n      }\n\n      button,\n      input,\n      select,\n      textarea {\n        font: inherit;\n      }\n\n      a {\n        color: inherit;\n      }\n\n      main {\n        width: min(1240px, calc(100vw - 28px));\n        margin: 0 auto;\n        padding: 20px 0 44px;\n      }\n\n      .topbar {\n        display: flex;\n        align-items: center;\n        justify-content: space-between;\n        gap: 16px;\n        padding: 12px 0 20px;\n      }\n\n      .brand {\n        display: flex;\n        align-items: center;\n        gap: 10px;\n        font-weight: 800;\n      }\n\n      .mark {\n        width: 34px;\n        height: 34px;\n        border-radius: 8px;\n        background: linear-gradient(135deg, var(--strong), var(--strong-2));\n        color: #fff;\n        display: grid;\n        place-items: center;\n        font-weight: 900;\n        box-shadow: 0 10px 24px rgba(12, 107, 93, 0.22);\n      }\n\n      .top-actions {\n        display: flex;\n        gap: 8px;\n        flex-wrap: wrap;\n        justify-content: flex-end;\n      }\n\n      .hero {\n        display: grid;\n        grid-template-columns: minmax(0, 1.1fr) minmax(340px, 0.62fr);\n        gap: 16px;\n        align-items: stretch;\n        position: relative;\n      }\n\n      .hero-copy,\n      .panel {\n        background: rgba(255, 255, 255, 0.93);\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        box-shadow: var(--shadow);\n      }\n\n      .hero-copy {\n        position: relative;\n        overflow: hidden;\n        min-height: 408px;\n        padding: clamp(22px, 4vw, 44px);\n        display: flex;\n        flex-direction: column;\n        justify-content: space-between;\n        isolation: isolate;\n        background:\n          linear-gradient(92deg, rgba(255, 255, 255, 0.97) 0%, rgba(255, 255, 255, 0.93) 46%, rgba(255, 255, 255, 0.1) 100%),\n          url(\"hero-account-security.png\") center right / cover no-repeat,\n          var(--surface);\n      }\n\n      .hero-copy::after {\n        content: \"\";\n        position: absolute;\n        inset: auto 24px 22px auto;\n        width: min(34%, 280px);\n        height: 1px;\n        background: linear-gradient(90deg, transparent, rgba(12, 107, 93, 0.6), transparent);\n        z-index: -1;\n      }\n\n      .hero-text {\n        max-width: 760px;\n      }\n\n      .eyebrow {\n        display: inline-flex;\n        align-items: center;\n        gap: 8px;\n        min-height: 30px;\n        margin: 0 0 12px;\n        padding: 0 10px;\n        border: 1px solid rgba(12, 107, 93, 0.24);\n        border-radius: 999px;\n        background: rgba(237, 244, 239, 0.82);\n        color: var(--strong);\n        font-size: 13px;\n        font-weight: 800;\n        text-transform: uppercase;\n      }\n\n      h1 {\n        margin: 0;\n        max-width: 760px;\n        font-size: clamp(34px, 5.4vw, 68px);\n        line-height: 1;\n        letter-spacing: 0;\n      }\n\n      .lead {\n        max-width: 690px;\n        margin: 18px 0 0;\n        color: #48545c;\n        font-size: clamp(16px, 2vw, 19px);\n        line-height: 1.55;\n      }\n\n      .hero-strip {\n        display: grid;\n        grid-template-columns: repeat(3, 1fr);\n        gap: 10px;\n        margin-top: 30px;\n        max-width: 720px;\n      }\n\n      .mini {\n        min-height: 92px;\n        padding: 14px;\n        border-radius: 8px;\n        border: 1px solid rgba(212, 221, 216, 0.88);\n        background: rgba(255, 255, 255, 0.86);\n        backdrop-filter: blur(10px);\n      }\n\n      .mini strong {\n        display: block;\n        font-size: 24px;\n        line-height: 1.05;\n      }\n\n      .mini span {\n        color: var(--muted);\n        font-size: 13px;\n        line-height: 1.35;\n      }\n\n      .control {\n        display: flex;\n        flex-direction: column;\n        justify-content: space-between;\n        padding: 22px;\n        background:\n          linear-gradient(180deg, rgba(17, 27, 32, 0.98), rgba(20, 39, 43, 0.96)),\n          var(--night);\n        color: #fff;\n        border-color: rgba(255, 255, 255, 0.16);\n      }\n\n      .control label,\n      .control .notice span {\n        color: #cddbd7;\n      }\n\n      .control-title {\n        margin: 0 0 14px;\n        font-size: 22px;\n        line-height: 1.2;\n      }\n\n      label {\n        display: block;\n        margin-bottom: 8px;\n        color: var(--muted);\n        font-size: 13px;\n        font-weight: 800;\n        text-transform: uppercase;\n      }\n\n      input,\n      textarea,\n      select {\n        width: 100%;\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: #fff;\n        color: var(--ink);\n        outline: none;\n      }\n\n      input,\n      select {\n        min-width: 0;\n        height: 46px;\n        padding: 0 12px;\n      }\n\n      textarea {\n        min-height: 148px;\n        padding: 12px;\n        resize: vertical;\n        line-height: 1.45;\n      }\n\n      input:focus,\n      select:focus,\n      textarea:focus {\n        border-color: var(--strong);\n        box-shadow: 0 0 0 3px rgba(15, 102, 87, 0.14);\n      }\n\n      .email-row {\n        display: grid;\n        grid-template-columns: 1fr auto;\n        gap: 8px;\n      }\n\n      .btn {\n        min-height: 42px;\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: #fff;\n        color: var(--ink);\n        cursor: pointer;\n        display: inline-flex;\n        align-items: center;\n        justify-content: center;\n        gap: 8px;\n        padding: 0 14px;\n        font-weight: 800;\n        text-decoration: none;\n        white-space: nowrap;\n      }\n\n      .btn:hover {\n        border-color: var(--strong);\n        transform: translateY(-1px);\n      }\n\n      .btn.primary {\n        border-color: var(--strong);\n        background: var(--strong);\n        color: #fff;\n        box-shadow: 0 10px 20px rgba(12, 107, 93, 0.18);\n      }\n\n      .btn.ghost {\n        background: rgba(255, 255, 255, 0.72);\n      }\n\n      .btn.danger {\n        color: var(--danger);\n      }\n\n      .notice {\n        margin-top: 14px;\n        padding: 13px;\n        border-radius: 8px;\n        background: rgba(255, 255, 255, 0.09);\n        border: 1px solid rgba(255, 255, 255, 0.12);\n        color: #edf5f2;\n        font-size: 14px;\n        line-height: 1.45;\n      }\n\n      .score-card {\n        margin-top: 16px;\n        padding: 16px;\n        border-radius: 8px;\n        background:\n          linear-gradient(135deg, rgba(12, 107, 93, 0.95), rgba(35, 95, 156, 0.92)),\n          #17201d;\n        color: #fff;\n        border: 1px solid rgba(255, 255, 255, 0.16);\n      }\n\n      .score-card strong {\n        display: block;\n        font-size: 38px;\n        line-height: 1;\n      }\n\n      .score-card span {\n        color: #c6d5d0;\n        font-size: 13px;\n      }\n\n      .tabs {\n        display: flex;\n        gap: 8px;\n        flex-wrap: wrap;\n        margin: 18px 0;\n        position: sticky;\n        top: 0;\n        z-index: 5;\n        padding: 10px 0;\n        background: rgba(247, 248, 244, 0.88);\n        backdrop-filter: blur(14px);\n      }\n\n      .tab {\n        border-color: transparent;\n      }\n\n      .tab.active {\n        border-color: var(--strong);\n        background: var(--strong);\n        color: #fff;\n      }\n\n      .view {\n        display: none;\n      }\n\n      .view.active {\n        display: block;\n      }\n\n      .grid {\n        display: grid;\n        grid-template-columns: repeat(3, minmax(0, 1fr));\n        gap: 12px;\n      }\n\n      .section {\n        padding: 18px;\n        margin-bottom: 18px;\n      }\n\n      .section h2 {\n        margin: 0 0 12px;\n        font-size: 21px;\n        letter-spacing: 0;\n      }\n\n      .section-sub {\n        margin: -4px 0 14px;\n        color: var(--muted);\n        line-height: 1.45;\n      }\n\n      .section h2::before {\n        content: \"\";\n        display: inline-block;\n        width: 8px;\n        height: 22px;\n        margin-right: 10px;\n        border-radius: 999px;\n        background: linear-gradient(180deg, var(--strong), var(--accent));\n        vertical-align: -4px;\n      }\n\n      .link-card,\n      .task,\n      .account-row {\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: #fff;\n      }\n\n      .link-card {\n        min-height: 116px;\n        padding: 14px;\n        display: flex;\n        flex-direction: column;\n        justify-content: space-between;\n        gap: 12px;\n        text-decoration: none;\n        transition: border-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;\n      }\n\n      .link-card:hover {\n        border-color: var(--strong-2);\n        transform: translateY(-2px);\n        box-shadow: 0 12px 26px rgba(21, 25, 29, 0.09);\n      }\n\n      .link-card strong {\n        display: block;\n      }\n\n      .link-card span,\n      .task span,\n      .account-row span {\n        color: var(--muted);\n        font-size: 13px;\n        line-height: 1.38;\n      }\n\n      .checklist {\n        display: grid;\n        grid-template-columns: repeat(2, minmax(0, 1fr));\n        gap: 10px;\n      }\n\n      .task {\n        display: grid;\n        grid-template-columns: auto 1fr;\n        gap: 10px;\n        align-items: start;\n        padding: 12px;\n      }\n\n      .task input {\n        width: 18px;\n        height: 18px;\n        margin-top: 2px;\n        accent-color: var(--strong);\n      }\n\n      .task strong {\n        display: block;\n        margin-bottom: 4px;\n      }\n\n      .account-form {\n        display: grid;\n        grid-template-columns: 1.2fr 0.9fr 0.9fr auto;\n        gap: 8px;\n        align-items: end;\n      }\n\n      .filter-row {\n        display: grid;\n        grid-template-columns: 1fr 190px 190px;\n        gap: 8px;\n        margin-top: 14px;\n      }\n\n      .import-box {\n        display: grid;\n        grid-template-columns: 1fr auto;\n        gap: 8px;\n        align-items: end;\n        margin-bottom: 14px;\n      }\n\n      .source-grid {\n        display: grid;\n        grid-template-columns: repeat(3, minmax(0, 1fr));\n        gap: 10px;\n        margin-bottom: 14px;\n      }\n\n      .source-card {\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: #fff;\n        padding: 12px;\n        border-left: 4px solid var(--strong);\n      }\n\n      .source-card strong {\n        display: block;\n        margin-bottom: 5px;\n      }\n\n      .source-card span {\n        color: var(--muted);\n        font-size: 13px;\n        line-height: 1.35;\n      }\n\n      .account-list {\n        display: grid;\n        gap: 8px;\n        margin-top: 12px;\n      }\n\n      .account-row {\n        display: grid;\n        grid-template-columns: 1fr auto auto auto auto auto auto;\n        gap: 10px;\n        align-items: center;\n        padding: 12px;\n        border-left: 4px solid transparent;\n        transition: border-color 160ms ease, background 160ms ease, transform 160ms ease;\n      }\n\n      .account-row:hover {\n        transform: translateY(-1px);\n        border-color: rgba(35, 95, 156, 0.45);\n      }\n\n      .account-row.confirmed {\n        border-color: rgba(22, 128, 95, 0.55);\n        background: #f5fbf8;\n      }\n\n      .account-row.discarded {\n        opacity: 0.68;\n        background: #f8f7f4;\n      }\n\n      .tag {\n        display: inline-flex;\n        align-items: center;\n        justify-content: center;\n        min-height: 28px;\n        border-radius: 999px;\n        padding: 0 10px;\n        font-size: 12px;\n        font-weight: 800;\n        background: #edf2f7;\n        color: #324155;\n      }\n\n      .tag.high {\n        background: #ffe8e6;\n        color: #8d2d27;\n      }\n\n      .tag.medium {\n        background: #fff2d8;\n        color: #875000;\n      }\n\n      .tag.low {\n        background: #e5f4ec;\n        color: #176344;\n      }\n\n      .tag.found {\n        background: #e5f4ec;\n        color: #176344;\n      }\n\n      .tag.candidate {\n        background: #edf2f7;\n        color: #324155;\n      }\n\n      .two-col {\n        display: grid;\n        grid-template-columns: 1fr 1fr;\n        gap: 18px;\n      }\n\n      .pill-list {\n        display: flex;\n        gap: 8px;\n        flex-wrap: wrap;\n      }\n\n      .pill {\n        border: 1px solid var(--line);\n        border-radius: 999px;\n        padding: 8px 11px;\n        background: #fff;\n        color: var(--muted);\n        font-size: 13px;\n      }\n\n      .steps {\n        margin: 0;\n        padding-left: 20px;\n        color: var(--muted);\n        line-height: 1.55;\n      }\n\n      .steps li {\n        margin-bottom: 8px;\n      }\n\n      .empty {\n        padding: 14px;\n        border: 1px dashed var(--line);\n        border-radius: 8px;\n        color: var(--muted);\n        background: repeating-linear-gradient(\n          135deg,\n          rgba(255, 255, 255, 0.82),\n          rgba(255, 255, 255, 0.82) 10px,\n          rgba(237, 244, 239, 0.7) 10px,\n          rgba(237, 244, 239, 0.7) 20px\n        );\n      }\n\n      .log-list {\n        display: grid;\n        gap: 8px;\n      }\n\n      .log-item {\n        display: grid;\n        grid-template-columns: 150px 1fr;\n        gap: 10px;\n        align-items: start;\n        padding: 11px;\n        border: 1px solid var(--line);\n        border-radius: 8px;\n        background: #fff;\n        border-left: 4px solid var(--strong-2);\n      }\n\n      .log-time {\n        color: var(--muted);\n        font-size: 12px;\n        font-weight: 800;\n      }\n\n      .log-item strong {\n        display: block;\n        margin-bottom: 3px;\n      }\n\n      .log-item span {\n        color: var(--muted);\n        font-size: 13px;\n        line-height: 1.35;\n      }\n\n      .toast {\n        position: fixed;\n        right: 18px;\n        bottom: 18px;\n        max-width: min(360px, calc(100vw - 36px));\n        padding: 13px 15px;\n        border-radius: 8px;\n        background: #17201d;\n        color: #fff;\n        box-shadow: var(--shadow);\n        opacity: 0;\n        transform: translateY(8px);\n        pointer-events: none;\n        transition: 180ms ease;\n      }\n\n      .toast.show {\n        opacity: 1;\n        transform: translateY(0);\n      }\n\n      @media (max-width: 980px) {\n        .hero,\n        .two-col {\n          grid-template-columns: 1fr;\n        }\n\n        .grid,\n        .checklist {\n          grid-template-columns: repeat(2, minmax(0, 1fr));\n        }\n      }\n\n      @media (max-width: 700px) {\n        main {\n          width: min(100vw - 20px, 1240px);\n          padding-top: 10px;\n        }\n\n        .topbar,\n        .top-actions {\n          align-items: stretch;\n          flex-direction: column;\n        }\n\n        .hero-copy,\n        .control,\n        .section {\n          padding: 15px;\n        }\n\n        .email-row,\n        .hero-strip,\n        .grid,\n        .checklist,\n        .source-grid,\n        .import-box,\n        .account-form,\n        .filter-row,\n        .account-row,\n        .log-item {\n          grid-template-columns: 1fr;\n        }\n\n        .btn {\n          width: 100%;\n        }\n      }\n    </style>\n  </head>\n  <body>\n    <main>\n      <header class=\"topbar\">\n        <div class=\"brand\">\n          <div class=\"mark\" aria-hidden=\"true\">@</div>\n          <span>Account Finder Mail</span>\n        </div>\n        <div class=\"top-actions\">\n          <button class=\"btn ghost\" id=\"copyShare\" type=\"button\">Copia link</button>\n          <button class=\"btn ghost\" id=\"exportData\" type=\"button\">Esporta report</button>\n          <button class=\"btn danger\" id=\"resetData\" type=\"button\">Pulisci dati locali</button>\n        </div>\n      </header>\n\n      <section class=\"hero\">\n        <div class=\"hero-copy\">\n          <div class=\"hero-text\">\n            <p class=\"eyebrow\">Privacy-first, nessun account richiesto</p>\n            <h1>Trova indizi sugli account creati con una email.</h1>\n            <p class=\"lead\">\n              Non esiste un registro universale dei siti a cui sei iscritto.\n              Questa webapp ti aiuta a fare il lavoro bene: ricerche mirate,\n              checklist, account trovati, note e piano di bonifica.\n            </p>\n          </div>\n          <div class=\"hero-strip\">\n            <div class=\"mini\">\n              <strong id=\"doneCount\">0</strong>\n              <span>controlli completati</span>\n            </div>\n            <div class=\"mini\">\n              <strong id=\"accountCount\">0</strong>\n              <span>account annotati</span>\n            </div>\n            <div class=\"mini\">\n              <strong id=\"riskLabel\">Basso</strong>\n              <span>priorità stimata</span>\n            </div>\n          </div>\n        </div>\n\n        <aside class=\"panel control\">\n          <div>\n            <h2 class=\"control-title\">Avvia il controllo</h2>\n            <label for=\"email\">Email da controllare</label>\n            <div class=\"email-row\">\n              <input id=\"email\" type=\"email\" autocomplete=\"email\" placeholder=\"nome@email.com\" />\n              <button class=\"btn primary\" id=\"saveEmail\" type=\"button\">Crea lista</button>\n            </div>\n\n            <div class=\"notice\">\n              <strong>Come funziona davvero:</strong>\n              <span>Crea lista prepara i servizi da controllare. Scanner e Account trasformano email, CSV e testi copiati in registrazioni probabili.</span>\n            </div>\n          </div>\n\n          <div class=\"score-card\">\n            <strong id=\"scoreCount\">0%</strong>\n            <span>del percorso completato</span>\n          </div>\n        </aside>\n      </section>\n\n      <nav class=\"tabs\" aria-label=\"Sezioni\">\n        <button class=\"btn tab active\" data-view=\"search\" type=\"button\">Ricerche</button>\n        <button class=\"btn tab\" data-view=\"scanner\" type=\"button\">Scanner</button>\n        <button class=\"btn tab\" data-view=\"accounts\" type=\"button\">Account</button>\n        <button class=\"btn tab\" data-view=\"cleanup\" type=\"button\">Pulizia</button>\n        <button class=\"btn tab\" data-view=\"report\" type=\"button\">Report</button>\n        <button class=\"btn tab\" data-view=\"log\" type=\"button\">Log</button>\n      </nav>\n\n      <section class=\"view active\" id=\"view-search\">\n        <div class=\"panel section\">\n          <h2>Ricerche veloci</h2>\n          <p class=\"section-sub\">\n            Prima inserisci l'email, poi apri solo i controlli che vuoi fare.\n          </p>\n          <div class=\"grid\" id=\"quickLinks\"></div>\n        </div>\n\n        <div class=\"panel section\">\n          <h2>Checklist investigazione</h2>\n          <div class=\"checklist\" id=\"checklist\"></div>\n        </div>\n\n        <div class=\"panel section\">\n          <h2>Parole da cercare nella casella email</h2>\n          <div class=\"pill-list\" id=\"keywords\"></div>\n        </div>\n      </section>\n\n      <section class=\"view\" id=\"view-scanner\">\n        <div class=\"panel section\">\n          <h2>Scanner da fonti reali</h2>\n          <p class=\"section-sub\">\n            Incolla dati che possiedi o risultati pubblici: email ricevute, export password manager, risultati web copiati cercando la mail.\n          </p>\n          <div class=\"source-grid\">\n            <div class=\"source-card\">\n              <strong>Email ricevute</strong>\n              <span>Oggetti, mittenti, anteprime o export della posta.</span>\n            </div>\n            <div class=\"source-card\">\n              <strong>Password manager</strong>\n              <span>CSV esportato da browser, Google Password Manager, Bitwarden o 1Password.</span>\n            </div>\n            <div class=\"source-card\">\n              <strong>Web pubblico</strong>\n              <span>Risultati copiati da Google, Bing o DuckDuckGo cercando la mail tra virgolette.</span>\n            </div>\n          </div>\n          <label for=\"evidenceDump\">Dati da analizzare</label>\n          <textarea\n            id=\"evidenceDump\"\n            placeholder=\"Incolla qui email, CSV password manager o risultati web. Esempi: noreply@netflix.com, https://github.com/login, Welcome to Spotify, password reset Amazon...\"\n          ></textarea>\n          <div style=\"margin-top: 10px\">\n            <label for=\"evidenceFile\">Oppure importa un file .txt/.csv</label>\n            <input id=\"evidenceFile\" type=\"file\" accept=\".txt,.csv,.eml,.md,text/plain,text/csv\" />\n          </div>\n          <div class=\"top-actions\" style=\"margin-top: 10px\">\n            <button class=\"btn primary\" id=\"deepScan\" type=\"button\">Analizza e crea lista</button>\n            <button class=\"btn\" id=\"importOutlookReport\" type=\"button\">Importa report Outlook</button>\n            <button class=\"btn\" id=\"makeSearchPack\" type=\"button\">Crea ricerche web</button>\n          </div>\n          <div id=\"searchPack\" class=\"account-list\"></div>\n        </div>\n      </section>\n\n      <section class=\"view\" id=\"view-accounts\">\n        <div class=\"panel section\">\n          <h2>Account trovati</h2>\n          <p class=\"section-sub\">\n            Qui vedi la lista. I servizi generati sono “da verificare”; quelli estratti da testi/email sono piu concreti.\n          </p>\n          <div class=\"import-box\">\n            <div>\n              <label for=\"mailDump\">Incolla testi o email ricevute</label>\n              <textarea\n                id=\"mailDump\"\n                placeholder=\"Incolla qui oggetto, mittente o testo di email tipo: Welcome to Dropbox, conferma account Netflix, noreply@spotify.com...\"\n              ></textarea>\n            </div>\n            <button class=\"btn primary\" id=\"scanText\" type=\"button\">Estrai registrazioni</button>\n          </div>\n          <div class=\"account-form\">\n            <div>\n              <label for=\"serviceName\">Servizio</label>\n              <input id=\"serviceName\" placeholder=\"Esempio: Dropbox\" />\n            </div>\n            <div>\n              <label for=\"serviceStatus\">Stato</label>\n              <select id=\"serviceStatus\">\n                <option>Da verificare</option>\n                <option>Attivo</option>\n                <option>Da eliminare</option>\n                <option>Eliminato</option>\n              </select>\n            </div>\n            <div>\n              <label for=\"serviceRisk\">Priorità</label>\n              <select id=\"serviceRisk\">\n                <option value=\"medium\">Media</option>\n                <option value=\"high\">Alta</option>\n                <option value=\"low\">Bassa</option>\n              </select>\n            </div>\n            <button class=\"btn primary\" id=\"addAccount\" type=\"button\">Aggiungi</button>\n          </div>\n          <div class=\"filter-row\">\n            <input id=\"accountSearch\" placeholder=\"Filtra per servizio, dominio o prova\" />\n            <select id=\"sourceFilter\">\n              <option value=\"all\">Tutte le fonti</option>\n              <option value=\"import\">Estratti da fonte reale</option>\n              <option value=\"candidate\">Da verificare</option>\n              <option value=\"manual\">Manuali</option>\n            </select>\n            <select id=\"riskFilter\">\n              <option value=\"all\">Tutte le priorita</option>\n              <option value=\"high\">Alta</option>\n              <option value=\"medium\">Media</option>\n              <option value=\"low\">Bassa</option>\n            </select>\n          </div>\n          <div class=\"account-list\" id=\"accountList\"></div>\n        </div>\n      </section>\n\n      <section class=\"view\" id=\"view-cleanup\">\n        <div class=\"two-col\">\n          <div class=\"panel section\">\n            <h2>Piano di pulizia</h2>\n            <ol class=\"steps\">\n              <li>Proteggi prima email principale, banca, SPID, lavoro e cloud con password uniche e 2FA.</li>\n              <li>Chiudi o anonimizza gli account inutili, iniziando da quelli con priorità alta.</li>\n              <li>Revoca accessi “Accedi con Google/Apple/Facebook” che non riconosci.</li>\n              <li>Disiscriviti dalle newsletter solo quando arrivano da mittenti affidabili.</li>\n              <li>Ripeti il controllo ogni 6-12 mesi o dopo una violazione importante.</li>\n            </ol>\n          </div>\n\n          <div class=\"panel section\">\n            <h2>Note private</h2>\n            <textarea\n              id=\"notes\"\n              placeholder=\"Esempio: vecchio forum da cancellare, Dropbox attivo, newsletter già rimossa...\"\n            ></textarea>\n            <div class=\"top-actions\" style=\"margin-top: 10px\">\n              <button class=\"btn primary\" id=\"copyPlan\" type=\"button\">Copia piano</button>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"view\" id=\"view-report\">\n        <div class=\"panel section\">\n          <h2>Report pronto</h2>\n          <p class=\"section-sub\">\n            Il report viene generato dai dati salvati solo in questo browser.\n          </p>\n          <textarea id=\"reportText\" readonly></textarea>\n          <div class=\"top-actions\" style=\"margin-top: 10px\">\n            <button class=\"btn primary\" id=\"copyReport\" type=\"button\">Copia report</button>\n            <button class=\"btn\" id=\"exportCsv\" type=\"button\">Esporta CSV</button>\n          </div>\n        </div>\n      </section>\n\n      <section class=\"view\" id=\"view-log\">\n        <div class=\"panel section\">\n          <h2>Log processo</h2>\n          <p class=\"section-sub\">\n            Qui vedi cosa ha fatto l'app: lista generata, scanner eseguiti, risultati aggiunti, report copiati o esportati.\n          </p>\n          <div class=\"top-actions\" style=\"margin-bottom: 12px\">\n            <button class=\"btn primary\" id=\"copyLog\" type=\"button\">Copia log</button>\n            <button class=\"btn danger\" id=\"clearLog\" type=\"button\">Pulisci log</button>\n          </div>\n          <div id=\"processLog\" class=\"log-list\"></div>\n        </div>\n      </section>\n    </main>\n\n    <div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n    <script>\n      const STORAGE_KEY = \"account-finder-mail-v2\";\n      const $ = (selector) => document.querySelector(selector);\n      const emailInput = $(\"#email\");\n      const notesInput = $(\"#notes\");\n      const quickLinks = $(\"#quickLinks\");\n      const checklistEl = $(\"#checklist\");\n      const accountList = $(\"#accountList\");\n      const reportText = $(\"#reportText\");\n      const mailDump = $(\"#mailDump\");\n      const evidenceDump = $(\"#evidenceDump\");\n      const processLog = $(\"#processLog\");\n      const evidenceFile = $(\"#evidenceFile\");\n      const accountSearch = $(\"#accountSearch\");\n      const sourceFilter = $(\"#sourceFilter\");\n      const riskFilter = $(\"#riskFilter\");\n\n      const checks = [\n        [\"mail-search\", \"Cerca nella casella email\", \"welcome, verify, conferma, registrazione, password reset, unsubscribe.\"],\n        [\"password-manager\", \"Controlla password manager\", \"Chrome, Safari, Edge, Firefox, Apple Password, Google Password Manager, 1Password o Bitwarden.\"],\n        [\"social-login\", \"Controlla accessi social\", \"Google, Apple, Facebook e Microsoft mostrano app e siti collegati.\"],\n        [\"breaches\", \"Controlla violazioni note\", \"Have I Been Pwned segnala breach pubblici collegati alla mail.\"],\n        [\"public-search\", \"Cerca la mail online\", \"Usa la ricerca con virgolette per pagine, forum o documenti indicizzati.\"],\n        [\"cleanup\", \"Prepara eliminazioni\", \"Decidi cosa tenere, cosa chiudere e cosa proteggere con 2FA.\"]\n      ];\n\n      const keywords = [\n        \"welcome\", \"verify email\", \"confirm your email\", \"conferma iscrizione\",\n        \"registrazione\", \"password reset\", \"unsubscribe\", \"delete account\",\n        \"privacy\", \"GDPR\", \"two-factor\", \"invoice\", \"receipt\", \"newsletter\"\n      ];\n\n      const starterServices = [\n        [\"Google\", \"https://myaccount.google.com\", \"high\"],\n        [\"Apple ID\", \"https://account.apple.com\", \"high\"],\n        [\"Microsoft\", \"https://account.microsoft.com\", \"high\"],\n        [\"Meta / Facebook\", \"https://www.facebook.com\", \"medium\"],\n        [\"Amazon\", \"https://www.amazon.it\", \"high\"],\n        [\"PayPal\", \"https://www.paypal.com\", \"high\"],\n        [\"Netflix\", \"https://www.netflix.com\", \"medium\"],\n        [\"Spotify\", \"https://www.spotify.com\", \"medium\"],\n        [\"Dropbox\", \"https://www.dropbox.com\", \"medium\"],\n        [\"LinkedIn\", \"https://www.linkedin.com\", \"medium\"],\n        [\"GitHub\", \"https://github.com\", \"medium\"],\n        [\"Adobe\", \"https://account.adobe.com\", \"medium\"],\n        [\"Booking.com\", \"https://www.booking.com\", \"medium\"],\n        [\"eBay\", \"https://www.ebay.it\", \"medium\"]\n      ];\n\n      const linkTemplates = [\n        [\"Google: email pubblica\", \"Cerca pagine indicizzate con la mail esatta.\", (email) => `https://www.google.com/search?q=${encodeURIComponent('\"' + email + '\"')}`, true],\n        [\"Have I Been Pwned\", \"Verifica se la mail compare in data breach pubblici.\", (email) => `https://haveibeenpwned.com/account/${encodeURIComponent(email)}`, true],\n        [\"Gmail: account e iscrizioni\", \"Apre una ricerca Gmail con termini tipici.\", (email) => `https://mail.google.com/mail/u/0/#search/${encodeURIComponent(`(${email}) (welcome OR verify OR unsubscribe OR registrazione OR \"password reset\")`)}`, true],\n        [\"Outlook: account e iscrizioni\", \"Apre una ricerca Outlook per messaggi di account.\", (email) => `https://outlook.live.com/mail/0/search/id/${encodeURIComponent(`${email} welcome verify unsubscribe registrazione`)}`, true],\n        [\"Google app collegate\", \"Controlla servizi e app con accesso all'account Google.\", () => \"https://myaccount.google.com/connections\", false],\n        [\"Apple ID\", \"Verifica le app collegate con Accedi con Apple.\", () => \"https://account.apple.com/account/manage\", false],\n        [\"Facebook app e siti\", \"Revoca app non riconosciute collegate a Meta.\", () => \"https://www.facebook.com/settings?tab=applications\", false],\n        [\"Microsoft privacy\", \"Controlla sicurezza e accessi Microsoft.\", () => \"https://account.microsoft.com/privacy\", false],\n        [\"Google Password Manager\", \"Sfoglia password salvate nel tuo account Google.\", () => \"https://passwords.google.com\", false]\n      ];\n\n      function readState() {\n        try {\n          const state = JSON.parse(localStorage.getItem(STORAGE_KEY)) || {};\n          return { done: {}, accounts: [], mailDump: \"\", evidenceDump: \"\", logs: [], ...state };\n        } catch {\n          return { done: {}, accounts: [], mailDump: \"\", evidenceDump: \"\", logs: [] };\n        }\n      }\n\n      function writeState(state) {\n        localStorage.setItem(STORAGE_KEY, JSON.stringify(state));\n      }\n\n      function toast(message) {\n        const el = $(\"#toast\");\n        el.textContent = message;\n        el.classList.add(\"show\");\n        window.clearTimeout(toast.timer);\n        toast.timer = window.setTimeout(() => el.classList.remove(\"show\"), 2200);\n      }\n\n      function getStateFromUi() {\n        const saved = readState();\n        return {\n          email: emailInput.value.trim(),\n          notes: notesInput.value,\n          mailDump: mailDump.value,\n          evidenceDump: evidenceDump.value,\n          done: saved.done || {},\n          accounts: saved.accounts || [],\n          logs: saved.logs || []\n        };\n      }\n\n      function persist() {\n        writeState(getStateFromUi());\n        renderAll();\n      }\n\n      function riskText(value) {\n        return { high: \"Alta\", medium: \"Media\", low: \"Bassa\" }[value] || \"Media\";\n      }\n\n      function renderLinks() {\n        const email = emailInput.value.trim();\n        quickLinks.innerHTML = \"\";\n        linkTemplates.forEach(([label, help, buildUrl, needsEmail]) => {\n          const anchor = document.createElement(\"a\");\n          anchor.className = \"link-card\";\n          anchor.target = \"_blank\";\n          anchor.rel = \"noreferrer\";\n          anchor.href = needsEmail && !email ? \"#\" : buildUrl(email);\n          if (needsEmail && !email) {\n            anchor.addEventListener(\"click\", (event) => {\n              event.preventDefault();\n              toast(\"Inserisci prima un'email.\");\n            });\n          }\n          anchor.innerHTML = `<strong>${label}</strong><span>${help}</span>`;\n          quickLinks.append(anchor);\n        });\n      }\n\n      function renderChecklist() {\n        const state = readState();\n        checklistEl.innerHTML = \"\";\n        checks.forEach(([id, title, detail]) => {\n          const label = document.createElement(\"label\");\n          label.className = \"task\";\n          label.innerHTML = `\n            <input type=\"checkbox\" data-id=\"${id}\" ${state.done?.[id] ? \"checked\" : \"\"} />\n            <span><strong>${title}</strong><span>${detail}</span></span>\n          `;\n          checklistEl.append(label);\n        });\n      }\n\n      function renderAccounts() {\n        const state = readState();\n        $(\"#accountCount\").textContent = state.accounts?.length || 0;\n        accountList.innerHTML = \"\";\n        if (!state.accounts?.length) {\n          accountList.innerHTML = `<div class=\"empty\">Nessuna registrazione in lista. Premi “Crea lista” o incolla email/testi e poi “Estrai registrazioni”.</div>`;\n          return;\n        }\n        const query = accountSearch.value.trim().toLowerCase();\n        const visibleAccounts = state.accounts\n          .map((account, index) => ({ account, index }))\n          .filter(({ account }) => sourceFilter.value === \"all\" || account.source === sourceFilter.value)\n          .filter(({ account }) => riskFilter.value === \"all\" || account.risk === riskFilter.value)\n          .filter(({ account }) => {\n            if (!query) return true;\n            return `${account.name} ${account.url || \"\"} ${account.status || \"\"}`.toLowerCase().includes(query);\n          });\n        if (!visibleAccounts.length) {\n          accountList.innerHTML = `<div class=\"empty\">Nessun risultato corrisponde ai filtri attivi.</div>`;\n          return;\n        }\n        visibleAccounts.forEach(({ account, index }) => {\n          const row = document.createElement(\"div\");\n          const rowState = account.status?.toLowerCase().includes(\"scartato\")\n            ? \"discarded\"\n            : account.source === \"import\" || account.status?.toLowerCase().includes(\"confermata\")\n              ? \"confirmed\"\n              : \"\";\n          row.className = `account-row ${rowState}`;\n          row.innerHTML = `\n            <div>\n              <strong>${escapeHtml(account.name)}</strong><br />\n              <span>${escapeHtml(account.status)}${account.url ? ` - ${escapeHtml(account.url)}` : \"\"}</span>\n            </div>\n            <span class=\"tag ${account.source === \"import\" ? \"found\" : \"candidate\"}\">${account.source === \"import\" ? \"Estratto\" : \"Da verificare\"}</span>\n            <span class=\"tag\">${account.confidence ? `${account.confidence}%` : \"n/d\"}</span>\n            <span class=\"tag ${account.risk}\">${riskText(account.risk)}</span>\n            <button class=\"btn\" data-confirm=\"${index}\" type=\"button\">Conferma</button>\n            <button class=\"btn\" data-discard=\"${index}\" type=\"button\">Scarta</button>\n            <button class=\"btn danger\" data-remove=\"${index}\" type=\"button\">Rimuovi</button>\n          `;\n          accountList.append(row);\n        });\n      }\n\n      function renderKeywords() {\n        $(\"#keywords\").innerHTML = keywords.map((item) => `<span class=\"pill\">${item}</span>`).join(\"\");\n      }\n\n      function updateMetrics() {\n        const state = readState();\n        const done = checks.filter(([id]) => state.done?.[id]).length;\n        const score = Math.round((done / checks.length) * 100);\n        const highRisk = (state.accounts || []).some((account) => account.risk === \"high\");\n        $(\"#doneCount\").textContent = done;\n        $(\"#scoreCount\").textContent = `${score}%`;\n        $(\"#riskLabel\").textContent = highRisk ? \"Alta\" : state.accounts?.length ? \"Media\" : \"Bassa\";\n      }\n\n      function buildReport() {\n        const state = getStateFromUi();\n        const completed = checks.filter(([id]) => state.done[id]).map(([, title]) => `- [x] ${title}`);\n        const pending = checks.filter(([id]) => !state.done[id]).map(([, title]) => `- [ ] ${title}`);\n        const accounts = state.accounts.map((account) => `- ${account.name} | ${account.status} | ${account.source === \"import\" ? \"estratto da fonte reale\" : \"da verificare\"} | confidenza ${account.confidence || \"n/d\"}% | priorita ${riskText(account.risk)}`);\n        return [\n          \"Account Finder Mail - report\",\n          `Email: ${state.email || \"non indicata\"}`,\n          `Generato: ${new Date().toLocaleString(\"it-IT\")}`,\n          \"\",\n          \"Controlli completati:\",\n          completed.length ? completed.join(\"\\n\") : \"- nessuno\",\n          \"\",\n          \"Controlli da fare:\",\n          pending.length ? pending.join(\"\\n\") : \"- nessuno\",\n          \"\",\n          \"Account annotati:\",\n          accounts.length ? accounts.join(\"\\n\") : \"- nessuno\",\n          \"\",\n          \"Note:\",\n          state.notes || \"nessuna nota\"\n        ].join(\"\\n\");\n      }\n\n      function csvValue(value) {\n        return `\"${String(value ?? \"\").replaceAll('\"', '\"\"')}\"`;\n      }\n\n      function buildCsv() {\n        const state = getStateFromUi();\n        const rows = [\n          [\"servizio\", \"dominio_o_url\", \"stato\", \"fonte\", \"confidenza\", \"priorita\"],\n          ...state.accounts.map((account) => [\n            account.name,\n            account.url || \"\",\n            account.status || \"\",\n            account.source || \"\",\n            account.confidence || \"\",\n            riskText(account.risk)\n          ])\n        ];\n        return rows.map((row) => row.map(csvValue).join(\",\")).join(\"\\n\");\n      }\n\n      function downloadText(content, filename, type) {\n        const blob = new Blob([content], { type });\n        const link = document.createElement(\"a\");\n        link.href = URL.createObjectURL(blob);\n        link.download = filename;\n        link.click();\n        URL.revokeObjectURL(link.href);\n      }\n\n      function addAccounts(newAccounts) {\n        const state = getStateFromUi();\n        const known = new Set(state.accounts.map((item) => item.name.toLowerCase()));\n        let added = 0;\n        newAccounts.forEach((account) => {\n          const key = account.name.toLowerCase();\n          if (known.has(key)) return;\n          known.add(key);\n          state.accounts.push(account);\n          added += 1;\n        });\n        writeState(state);\n        renderAll();\n        return added;\n      }\n\n      function logEvent(action, detail) {\n        const state = getStateFromUi();\n        const entry = {\n          time: new Date().toLocaleString(\"it-IT\"),\n          action,\n          detail\n        };\n        state.logs = [entry, ...(state.logs || [])].slice(0, 80);\n        writeState(state);\n        renderAll();\n      }\n\n      function buildLogText() {\n        const state = readState();\n        if (!state.logs?.length) return \"Nessun evento registrato.\";\n        return state.logs.map((item) => `[${item.time}] ${item.action}: ${item.detail}`).join(\"\\n\");\n      }\n\n      function renderProcessLog() {\n        const state = readState();\n        if (!state.logs?.length) {\n          processLog.innerHTML = `<div class=\"empty\">Il log e vuoto. Esegui una scansione, crea una lista o importa dati per vedere il processo.</div>`;\n          return;\n        }\n        processLog.innerHTML = state.logs\n          .map((item) => `\n            <div class=\"log-item\">\n              <div class=\"log-time\">${escapeHtml(item.time)}</div>\n              <div><strong>${escapeHtml(item.action)}</strong><span>${escapeHtml(item.detail)}</span></div>\n            </div>\n          `)\n          .join(\"\");\n      }\n\n      function createStarterList() {\n        const email = emailInput.value.trim();\n        if (!email) {\n          toast(\"Inserisci prima un'email.\");\n          return;\n        }\n        const generated = starterServices.map(([name, url, risk]) => ({\n          name,\n          url,\n          status: \"Possibile registrazione da verificare\",\n          risk,\n          source: \"candidate\"\n        }));\n        const added = addAccounts(generated);\n        document.querySelector('[data-view=\"accounts\"]').click();\n        toast(added ? `${added} servizi aggiunti alla lista.` : \"La lista era gia aggiornata.\");\n      }\n\n      function renderSearchPack() {\n        const email = emailInput.value.trim();\n        const box = $(\"#searchPack\");\n        if (!email) {\n          box.innerHTML = `<div class=\"empty\">Inserisci l'email per generare query web da copiare.</div>`;\n          return;\n        }\n        const queries = [\n          `\"${email}\"`,\n          `\"${email}\" account`,\n          `\"${email}\" login`,\n          `\"${email}\" \"password reset\"`,\n          `\"${email}\" \"welcome\"`,\n          `\"${email}\" \"unsubscribe\"`\n        ];\n        box.innerHTML = queries\n          .map((query) => `<a class=\"link-card\" target=\"_blank\" rel=\"noreferrer\" href=\"https://www.google.com/search?q=${encodeURIComponent(query)}\"><strong>${escapeHtml(query)}</strong><span>Apri ricerca web pubblica</span></a>`)\n          .join(\"\");\n      }\n\n      function importMarkdownFindings(text) {\n        return text\n          .split(\"\\n\")\n          .map((line) => line.trim())\n          .filter((line) => line.startsWith(\"|\") && !line.includes(\"---\") && !line.includes(\"Servizio |\"))\n          .map((line) => line.split(\"|\").map((cell) => cell.trim()).filter(Boolean))\n          .filter((cells) => cells.length >= 4)\n          .map(([name, evidence, confidence, priority]) => ({\n            name,\n            url: \"\",\n            status: `${evidence} (${confidence})`,\n            risk: priority.toLowerCase().includes(\"alta\") ? \"high\" : priority.toLowerCase().includes(\"media\") ? \"medium\" : \"low\",\n            source: \"import\",\n            confidence: confidence.toLowerCase().includes(\"alta\") ? 92 : confidence.toLowerCase().includes(\"media\") ? 68 : 45\n          }));\n      }\n\n      function extractRegistrationsFromText(text) {\n        const domains = new Map();\n        const breachMatch = text.match(/(\\d+)\\s+data\\s+breach(?:es)?/i);\n        if (breachMatch) {\n          domains.set(\"data-breaches\", {\n            name: `${breachMatch[1]} data breach rilevati`,\n            evidence: breachMatch[0],\n            forceStatus: \"Data breach confermato da fonte esterna: controllare dettagli e cambiare password riutilizzate\",\n            forceRisk: \"high\",\n            forceConfidence: 95\n          });\n        }\n        const emailMatches = text.match(/[A-Z0-9._%+-]+@([A-Z0-9.-]+\\.[A-Z]{2,})/gi) || [];\n        emailMatches.forEach((mail) => {\n          const domain = mail.split(\"@\").pop().toLowerCase().replace(/^mail\\.|^email\\.|^noreply\\.|^no-reply\\./, \"\");\n          domains.set(domain, { name: serviceNameFromDomain(domain), evidence: mail });\n        });\n\n        const urlMatches = text.match(/https?:\\/\\/([A-Z0-9.-]+\\.[A-Z]{2,})[^\\s,;)]*/gi) || [];\n        urlMatches.forEach((url) => {\n          try {\n            const host = new URL(url).hostname.toLowerCase().replace(/^www\\./, \"\");\n            domains.set(host, { name: serviceNameFromDomain(host), evidence: url });\n          } catch {}\n        });\n\n        starterServices.forEach(([name, url, risk]) => {\n          const plain = name.toLowerCase().split(\" / \")[0];\n          if (text.toLowerCase().includes(plain)) {\n            const host = new URL(url).hostname.replace(/^www\\./, \"\");\n            domains.set(host, { name, evidence: `nome servizio trovato: ${name}` });\n          }\n        });\n\n        return [...domains.entries()].map(([domain, found]) => ({\n          name: found.name,\n          url: domain,\n          status: found.forceStatus || classifyEvidence(text, domain, found.evidence),\n          risk: found.forceRisk || guessRisk(domain),\n          source: \"import\",\n          confidence: found.forceConfidence || confidenceScore(text, domain)\n        }));\n      }\n\n      function classifyEvidence(text, domain, evidence) {\n        const lower = `${text} ${domain} ${evidence}`.toLowerCase();\n        if (/welcome|benvenut|registrazione|conferma account|verify|confirm|password reset|reset password|security code|codice di sicurezza|login/.test(lower)) {\n          return \"Registrazione probabile: prova forte nel testo\";\n        }\n        if (/invoice|receipt|ordine|fattura|payment|pagamento|subscription|abbonamento/.test(lower)) {\n          return \"Account o acquisto probabile: prova economica o abbonamento\";\n        }\n        if (/unsubscribe|newsletter|marketing/.test(lower)) {\n          return \"Iscrizione newsletter probabile\";\n        }\n        return \"Traccia trovata: da verificare\";\n      }\n\n      function confidenceScore(text, domain) {\n        const lower = `${text} ${domain}`.toLowerCase();\n        let score = 35;\n        if (/welcome|benvenut|registrazione|conferma account|verify|confirm/.test(lower)) score += 35;\n        if (/password reset|reset password|security code|codice di sicurezza|login/.test(lower)) score += 30;\n        if (/invoice|receipt|fattura|subscription|abbonamento|ordine/.test(lower)) score += 20;\n        if (/unsubscribe|newsletter/.test(lower)) score -= 10;\n        return Math.max(10, Math.min(score, 98));\n      }\n\n      function serviceNameFromDomain(domain) {\n        const core = domain.split(\".\").filter((part) => ![\"com\", \"it\", \"net\", \"org\", \"co\", \"io\", \"email\"].includes(part)).pop() || domain;\n        return core.charAt(0).toUpperCase() + core.slice(1).replaceAll(\"-\", \" \");\n      }\n\n      function guessRisk(domain) {\n        if (/bank|paypal|poste|amazon|google|apple|microsoft|icloud|account|stripe|wise|revolut/.test(domain)) return \"high\";\n        if (/netflix|spotify|dropbox|linkedin|facebook|instagram|booking|adobe|github/.test(domain)) return \"medium\";\n        return \"low\";\n      }\n\n      function renderReport() {\n        reportText.value = buildReport();\n      }\n\n      function renderAll() {\n        renderLinks();\n        renderAccounts();\n        updateMetrics();\n        renderReport();\n        renderProcessLog();\n      }\n\n      function escapeHtml(value) {\n        return String(value)\n          .replaceAll(\"&\", \"&amp;\")\n          .replaceAll(\"<\", \"&lt;\")\n          .replaceAll(\">\", \"&gt;\")\n          .replaceAll('\"', \"&quot;\")\n          .replaceAll(\"'\", \"&#039;\");\n      }\n\n      async function copyText(text, message) {\n        if (navigator.clipboard && window.isSecureContext) {\n          await navigator.clipboard.writeText(text);\n          toast(message);\n          return;\n        }\n        reportText.value = text;\n        reportText.focus();\n        reportText.select();\n        document.execCommand(\"copy\");\n        toast(message);\n      }\n\n      $(\".tabs\").addEventListener(\"click\", (event) => {\n        const tab = event.target.closest(\".tab\");\n        if (!tab) return;\n        document.querySelectorAll(\".tab\").forEach((item) => item.classList.remove(\"active\"));\n        document.querySelectorAll(\".view\").forEach((item) => item.classList.remove(\"active\"));\n        tab.classList.add(\"active\");\n        $(`#view-${tab.dataset.view}`).classList.add(\"active\");\n        renderReport();\n      });\n\n      $(\"#saveEmail\").addEventListener(\"click\", () => {\n        persist();\n        createStarterList();\n        logEvent(\"Lista iniziale creata\", \"Aggiunti servizi comuni da verificare in base alla mail inserita.\");\n      });\n      emailInput.addEventListener(\"change\", persist);\n      notesInput.addEventListener(\"input\", persist);\n      mailDump.addEventListener(\"input\", persist);\n      evidenceDump.addEventListener(\"input\", persist);\n      accountSearch.addEventListener(\"input\", renderAccounts);\n      sourceFilter.addEventListener(\"change\", renderAccounts);\n      riskFilter.addEventListener(\"change\", renderAccounts);\n      evidenceFile.addEventListener(\"change\", async () => {\n        const file = evidenceFile.files?.[0];\n        if (!file) return;\n        const text = await file.text();\n        evidenceDump.value = `${evidenceDump.value}\\n${text}`.trim();\n        persist();\n        logEvent(\"File importato\", `${file.name} e stato aggiunto allo scanner.`);\n        toast(\"File importato nello scanner.\");\n      });\n\n      checklistEl.addEventListener(\"change\", (event) => {\n        if (!event.target.matches(\"input[type='checkbox']\")) return;\n        const state = getStateFromUi();\n        state.done[event.target.dataset.id] = event.target.checked;\n        writeState(state);\n        renderAll();\n        logEvent(\"Checklist aggiornata\", `${event.target.checked ? \"Completato\" : \"Riaperto\"}: ${event.target.dataset.id}.`);\n      });\n\n      $(\"#addAccount\").addEventListener(\"click\", () => {\n        const name = $(\"#serviceName\").value.trim();\n        if (!name) {\n          toast(\"Inserisci il nome del servizio.\");\n          return;\n        }\n        const state = getStateFromUi();\n        state.accounts.push({\n          name,\n          status: $(\"#serviceStatus\").value,\n          risk: $(\"#serviceRisk\").value,\n          source: \"manual\"\n        });\n        writeState(state);\n        $(\"#serviceName\").value = \"\";\n        renderAll();\n        logEvent(\"Account manuale aggiunto\", `${name} e stato aggiunto alla lista.`);\n        toast(\"Account aggiunto.\");\n      });\n\n      $(\"#scanText\").addEventListener(\"click\", () => {\n        const found = extractRegistrationsFromText(mailDump.value);\n        if (!found.length) {\n          toast(\"Non ho trovato domini o servizi nel testo incollato.\");\n          return;\n        }\n        const added = addAccounts(found);\n        logEvent(\"Estrazione rapida\", `${added} nuove registrazioni estratte da testi/email incollati nella scheda Account.`);\n        toast(added ? `${added} registrazioni estratte.` : \"Nessuna nuova registrazione da aggiungere.\");\n      });\n\n      $(\"#deepScan\").addEventListener(\"click\", () => {\n        const combined = `${evidenceDump.value}\\n${mailDump.value}`;\n        const found = extractRegistrationsFromText(combined);\n        if (!found.length) {\n          toast(\"Non ho trovato prove utilizzabili nei dati incollati.\");\n          return;\n        }\n        const added = addAccounts(found);\n        document.querySelector('[data-view=\"accounts\"]').click();\n        logEvent(\"Scanner fonti reali\", `${added} nuovi risultati creati da email, export, URL o risultati web incollati.`);\n        toast(added ? `${added} risultati creati da fonti reali.` : \"Nessun nuovo risultato da aggiungere.\");\n      });\n\n      $(\"#importOutlookReport\").addEventListener(\"click\", () => {\n        const found = importMarkdownFindings(evidenceDump.value || mailDump.value);\n        if (!found.length) {\n          toast(\"Incolla prima il report Outlook in formato tabella Markdown.\");\n          return;\n        }\n        const added = addAccounts(found);\n        document.querySelector('[data-view=\"accounts\"]').click();\n        logEvent(\"Report Outlook importato\", `${added} risultati aggiunti dal report locale Outlook.`);\n        toast(added ? `${added} risultati Outlook importati.` : \"Risultati Outlook gia presenti.\");\n      });\n\n      $(\"#makeSearchPack\").addEventListener(\"click\", () => {\n        renderSearchPack();\n        logEvent(\"Ricerche web generate\", \"Create query mirate per cercare la mail nel web pubblico.\");\n        toast(\"Ricerche web create.\");\n      });\n\n      accountList.addEventListener(\"click\", (event) => {\n        const confirmButton = event.target.closest(\"[data-confirm]\");\n        const discardButton = event.target.closest(\"[data-discard]\");\n        const removeButton = event.target.closest(\"[data-remove]\");\n        if (!confirmButton && !discardButton && !removeButton) return;\n        const state = getStateFromUi();\n        const index = Number((confirmButton || discardButton || removeButton).dataset.confirm ?? (confirmButton || discardButton || removeButton).dataset.discard ?? (confirmButton || discardButton || removeButton).dataset.remove);\n        const account = state.accounts[index];\n        if (!account) return;\n        if (confirmButton) {\n          account.status = \"Registrazione confermata dall'utente\";\n          account.source = \"import\";\n          account.confidence = Math.max(account.confidence || 70, 95);\n          writeState(state);\n          renderAll();\n          logEvent(\"Account confermato\", `${account.name} e stato confermato.`);\n          return;\n        }\n        if (discardButton) {\n          account.status = \"Scartato: non risulta una registrazione utile\";\n          account.confidence = 5;\n          writeState(state);\n          renderAll();\n          logEvent(\"Account scartato\", `${account.name} e stato marcato come non utile.`);\n          return;\n        }\n        const removed = account.name || \"account\";\n        state.accounts.splice(index, 1);\n        writeState(state);\n        renderAll();\n        logEvent(\"Account rimosso\", `${removed} e stato rimosso dalla lista.`);\n      });\n\n      $(\"#exportData\").addEventListener(\"click\", () => {\n        downloadText(buildReport(), \"account-finder-report.txt\", \"text/plain;charset=utf-8\");\n        logEvent(\"Report esportato\", \"Scaricato il report testuale con account, confidenza, priorita e note.\");\n      });\n      $(\"#exportCsv\").addEventListener(\"click\", () => {\n        downloadText(buildCsv(), \"account-finder-registrazioni.csv\", \"text/csv;charset=utf-8\");\n        logEvent(\"CSV esportato\", \"Scaricata la tabella CSV delle registrazioni.\");\n      });\n\n      $(\"#copyPlan\").addEventListener(\"click\", () => copyText(buildReport(), \"Piano copiato.\"));\n      $(\"#copyReport\").addEventListener(\"click\", () => copyText(buildReport(), \"Report copiato.\"));\n      $(\"#copyShare\").addEventListener(\"click\", () => copyText(location.href, \"Link copiato.\"));\n      $(\"#copyLog\").addEventListener(\"click\", () => copyText(buildLogText(), \"Log copiato.\"));\n      $(\"#clearLog\").addEventListener(\"click\", () => {\n        const state = getStateFromUi();\n        state.logs = [];\n        writeState(state);\n        renderAll();\n        toast(\"Log pulito.\");\n      });\n\n      $(\"#resetData\").addEventListener(\"click\", () => {\n        if (!confirm(\"Pulire email, note, checklist e account salvati in questo browser?\")) return;\n        localStorage.removeItem(STORAGE_KEY);\n        emailInput.value = \"\";\n        notesInput.value = \"\";\n        renderChecklist();\n        renderAll();\n        toast(\"Dati locali puliti.\");\n      });\n\n      const initial = readState();\n      emailInput.value = initial.email || \"\";\n      notesInput.value = initial.notes || \"\";\n      mailDump.value = initial.mailDump || \"\";\n      evidenceDump.value = initial.evidenceDump || \"\";\n      renderChecklist();\n      renderKeywords();\n      renderAll();\n      renderSearchPack();\n    </script>\n  </body>\n</html>\n";
